(function () {
  var TURNS = [
    { you: "where is this week's reading?", ai: "On Canvas, under Modules." },
    { you: "TypeError: cannot read properties of undefined", ai: "Read the line before the crash, then the state it reads from." },
    { you: "add a footer with the class name", ai: "Edited src/App.jsx and ran the checks." },
    { you: "can you make me a practice exercise on React state?", ai: "Started a skill, and it built the page.", fire: "442-create-exercise" },
    { you: "is the old route still needed?", ai: "No, nothing links to it." },
    { you: "thanks, that worked", ai: "Any time." }
  ];
  var at = 0;
  var timer = null;

  function stop() {
    if (timer) { clearInterval(timer); timer = null; }
  }

  function make(i) {
    var t = TURNS[i];
    var box = document.createElement("div");
    box.className = "v71-b";
    var you = document.createElement("p");
    you.className = "v71-you";
    you.textContent = t.you;
    var ai = document.createElement("p");
    ai.className = "v71-ai";
    ai.textContent = t.ai;
    box.appendChild(you);
    box.appendChild(ai);
    if (t.fire) {
      var fire = document.createElement("p");
      fire.className = "v71-fire";
      fire.textContent = "skill " + t.fire + " loaded";
      box.appendChild(fire);
    }
    return box;
  }

  function paint(root) {
    var log = root.querySelector("[data-log]");
    var cost = root.querySelector("[data-cost]");
    var count = root.querySelector("[data-turn]");
    var bodyV = root.querySelector("[data-body-v]");
    var bodyP = root.querySelector("[data-body-p]");
    if (!log) return;

    var more = log.querySelector(".v71-more");
    if (!at) {
      log.textContent = "";
      var wait = document.createElement("p");
      wait.className = "v71-more";
      wait.textContent = "Nothing sent yet. Send the first message.";
      log.appendChild(wait);
    } else {
      if (more) log.removeChild(more);
      while (log.children.length > at) log.removeChild(log.lastChild);
      while (log.children.length < at) log.appendChild(make(log.children.length));
      log.scrollTop = log.scrollHeight;
    }

    var fired = at > 3;
    if (bodyV) bodyV.textContent = fired ? "in the window from message 4" : "waiting on disk";
    if (bodyP) {
      bodyP.textContent = fired ? "loaded once" : "not loaded";
      bodyP.className = "v71-pill" + (fired ? " v71-hot" : "");
    }
    if (count) count.textContent = at + (at === 1 ? " message" : " messages");
    if (cost) {
      cost.textContent = at === 0
        ? "Nothing sent yet."
        : fired
          ? at + " messages: " + at + " lines of the skill, and its file once, on message 4."
          : at + " messages: " + at + " lines of the skill, and none of its file.";
    }
  }

  return function (values, root, changed) {
    if (changed === "reset") { stop(); at = 0; }
    if (changed === "send") { stop(); if (at < TURNS.length) at += 1; }
    if (changed === "play") {
      stop();
      if (at >= TURNS.length) at = 0;
      timer = setInterval(function () {
        if (at >= TURNS.length) { stop(); return; }
        at += 1;
        paint(root);
      }, 900);
      root.__timer = timer;
    }
    paint(root);
  };
})()
